+package com.example.contact;
+
+import java.time.LocalDateTime;
+import java.time.format.DateTimeFormatter;
+import java.util.regex.Pattern;
+
+import com.example.about.AboutView;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.HasValue;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern.compile(EmailValidator.PATTERN);
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final DateTimeFormatter SENT_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
+
+    private final ContactMessageService service;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingLeave;
+
+    public ContactView(ContactMessageService service) {
+        this.service = service;
+
+        setPadding(true);
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(e -> sendButton.setEnabled(true));
+        email.addValueChangeListener(e -> sendButton.setEnabled(true));
+        phone.addValueChangeListener(e -> sendButton.setEnabled(true));
+        message.addValueChangeListener(e -> sendButton.setEnabled(true));
+
+        sendButton.addClickListener(e -> sendMessage());
+        Shortcuts.addShortcutListener(this, () -> {
+            if (sendButton.isEnabled()) {
+                sendMessage();
+            }
+        }, Key.ENTER);
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1), new FormLayout.ResponsiveStep("40em", 2));
+        form.setColspan(message, 2);
+
+        grid.addColumn(m -> SENT_FORMAT.format(m.sentAt())).setHeader("Sent").setAutoWidth(true);
+        grid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        grid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setAllRowsVisible(true);
+        refreshGrid();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form,
+                new HorizontalLayout(sendButton), grid);
+
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add(new Paragraph("The form has unsent input. Leave this page and throw it away?"));
+        Button keepEditing = new Button("Keep editing", e -> leaveDialog.close());
+        Button discard = new Button("Discard", e -> discardAndLeave());
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.getFooter().add(keepEditing, discard);
+        leaveDialog.addOpenedChangeListener(e -> {
+            if (!e.isOpened() && pendingLeave != null) {
+                pendingLeave.cancel();
+                pendingLeave = null;
+            }
+        });
+        add(leaveDialog);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasInput()) {
+            pendingLeave = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private void discardAndLeave() {
+        ContinueNavigationAction leave = pendingLeave;
+        pendingLeave = null;
+        leaveDialog.close();
+        if (leave != null) {
+            leave.proceed();
+        }
+    }
+
+    private boolean hasInput() {
+        return hasText(name) || hasText(email) || hasText(phone) || hasText(message);
+    }
+
+    private void sendMessage() {
+        if (!validate()) {
+            return;
+        }
+        service.add(new ContactMessage(trimmed(name), trimmed(email), trimmed(phone), trimmed(message),
+                LocalDateTime.now()));
+        refreshGrid();
+        Notification.show("Message sent");
+
+        // Clearing fires value change events, which would re-enable Send; disable it afterwards.
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        sendButton.setEnabled(false);
+    }
+
+    private boolean validate() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+
+        boolean valid = true;
+        if (trimmed(name).isEmpty()) {
+            reject(name, "Name is required");
+            valid = false;
+        }
+        if (!trimmed(email).isEmpty()) {
+            if (!EMAIL.matcher(trimmed(email)).matches()) {
+                reject(email, "Enter a valid e-mail address");
+                valid = false;
+            }
+        } else if (trimmed(phone).isEmpty()) {
+            reject(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (trimmed(message).isEmpty()) {
+            reject(message, "Message is required");
+            valid = false;
+        } else if (trimmed(message).length() > MAX_MESSAGE_LENGTH) {
+            reject(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+        return valid;
+    }
+
+    private void refreshGrid() {
+        grid.setItems(service.findNewestFirst());
+    }
+
+    private static void reject(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private static boolean hasText(HasValue<?, String> field) {
+        String value = field.getValue();
+        return value != null && !value.isEmpty();
+    }
+
+    private static String trimmed(HasValue<?, String> field) {
+        String value = field.getValue();
+        return value == null ? "" : value.trim();
+    }
+}
