+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/contact";
+    }
+
+    private void open(String path) {
+        page.navigate("http://localhost:" + port + path);
+        assertThat(page.locator("h1").filter(new Locator.FilterOptions().setHasText("Contact")).first())
+                .isVisible();
+    }
+
+    private Locator field(String label) {
+        return page.getByLabel(label, new Page.GetByLabelOptions().setExact(true));
+    }
+
+    private Locator send() {
+        return page.getByRole(AriaRole.BUTTON,
+                new Page.GetByRoleOptions().setName("Send"));
+    }
+
+    @Test
+    void emptySubmitShowsErrorsAndSendsNothing() {
+        open("/contact");
+        send().click();
+
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+        assertThat(page.getByText("Message sent")).hasCount(0);
+    }
+
+    @Test
+    void enterSendsAndDisablesSendUntilNextEdit() {
+        open("/contact");
+        field("Name").fill("Ada");
+        field("Email").fill("ada@example.com");
+        field("Message").fill("Hello from the browser");
+        field("Message").press("Enter");
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(field("Name")).hasValue("");
+        assertThat(send()).isDisabled();
+
+        field("Name").fill("Grace");
+        assertThat(send()).isEnabled();
+    }
+
+    @Test
+    void leavingWithInputAsksFirstAndDiscardNavigates() {
+        open("/contact");
+        field("Name").fill("Half typed");
+
+        page.getByRole(AriaRole.LINK,
+                new Page.GetByRoleOptions().setName("About")).click();
+
+        Locator keepEditing = page.getByRole(AriaRole.BUTTON,
+                new Page.GetByRoleOptions().setName("Keep editing"));
+        assertThat(keepEditing).isVisible();
+        keepEditing.click();
+        assertThat(keepEditing).isHidden();
+        assertThat(field("Name")).hasValue("Half typed");
+
+        page.getByRole(AriaRole.LINK,
+                new Page.GetByRoleOptions().setName("About")).click();
+        assertThat(keepEditing).isVisible();
+        page.getByRole(AriaRole.BUTTON,
+                new Page.GetByRoleOptions().setName("Discard")).click();
+
+        assertThat(page.locator("h1").filter(new Locator.FilterOptions().setHasText("About"))).isVisible();
+    }
+}
