+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private ContactView navigateToContact() {
+        return navigate(ContactView.class);
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    private Grid<ContactMessage> grid() {
+        return $(Grid.class).single();
+    }
+
+    private void fillValid() {
+        test(name()).setValue("Ada");
+        test(email()).setValue("ada@example.com");
+        test(message()).setValue("Hello there");
+    }
+
+    private void leaveViaAboutLink() {
+        test($(RouterLink.class).withText("About").single()).click();
+    }
+
+    @Test
+    void headingAndFieldsAreInPlace() {
+        navigateToContact();
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue(name().isEmpty());
+        assertTrue(email().isEmpty());
+        assertTrue(phone().isEmpty());
+        assertTrue(message().isEmpty());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void emptySubmitMarksFieldsAndSendsNothing() {
+        navigateToContact();
+        int before = grid().getGenericDataView().getItems().toList().size();
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertEquals(before, grid().getGenericDataView().getItems().toList().size());
+        assertFalse($(Notification.class).exists(), "no notification expected");
+    }
+
+    @Test
+    void invalidEmailIsRejectedAndPhoneAloneIsEnough() {
+        navigateToContact();
+        test(name()).setValue("Ada");
+        test(message()).setValue("Hi");
+        test(email()).setValue("not-an-address");
+        test(send()).click();
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+
+        test(email()).setValue("");
+        test(phone()).setValue("+358 40 123 4567");
+        test(send()).click();
+        assertFalse(email().isInvalid());
+        assertFalse(phone().isInvalid());
+    }
+
+    @Test
+    void overlongMessageIsRejected() {
+        navigateToContact();
+        fillValid();
+        test(message()).setValue("x".repeat(501));
+        test(send()).click();
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+    }
+
+    @Test
+    void validSubmitSendsClearsAndDisablesSend() {
+        navigateToContact();
+        fillValid();
+        test(send()).click();
+
+        assertTrue($(Notification.class).exists());
+        assertTrue(name().isEmpty());
+        assertTrue(email().isEmpty());
+        assertTrue(message().isEmpty());
+        assertFalse(send().isEnabled());
+
+        ContactMessage first = grid().getGenericDataView().getItems().findFirst().orElseThrow();
+        assertEquals("Ada", first.name());
+        assertEquals("Hello there", first.message());
+
+        test(name()).setValue("B");
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterKeySends() {
+        navigateToContact();
+        fillValid();
+        fireShortcut(Key.ENTER);
+        assertTrue(grid().getGenericDataView().getItems().findFirst().isPresent());
+    }
+
+    @Test
+    void sentMessagesSurviveLeavingTheView() {
+        navigateToContact();
+        test(name()).setValue("Persisted");
+        test(message()).setValue("Still here");
+        test(phone()).setValue("123");
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigateToContact();
+        assertTrue(grid().getGenericDataView().getItems()
+                .anyMatch(m -> "Persisted".equals(m.name()) && "Still here".equals(m.message())));
+    }
+
+    @Test
+    void leavingWithInputAsksFirstAndKeepEditingStays() {
+        navigateToContact();
+        test(name()).setValue("Half typed");
+
+        leaveViaAboutLink();
+
+        assertTrue($(Dialog.class).single().isOpened());
+        assertFalse($(AboutView.class).exists());
+        $(Button.class).withText("Keep editing").single().click();
+
+        assertFalse($(Dialog.class).exists());
+        assertEquals("Half typed", name().getValue());
+        assertTrue($(H1.class).withText("Contact").exists());
+    }
+
+    @Test
+    void discardingNavigatesAway() {
+        navigateToContact();
+        test(name()).setValue("Throw me away");
+
+        leaveViaAboutLink();
+        $(Button.class).withText("Discard").single().click();
+
+        assertTrue($(H1.class).withText("About").exists());
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotAsk() {
+        navigateToContact();
+
+        leaveViaAboutLink();
+
+        assertTrue($(H1.class).withText("About").exists());
+        assertFalse($(Dialog.class).exists());
+    }
+}
